    extern __shared__ half shared_data[];

    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    // Handle elements in chunks of stride
    for (int base_offset = 0; base_offset < total_elements; base_offset += stride) {
        // Load data into shared memory
        int local_idx = tid;
        if (local_idx < dim_size && (base_offset + local_idx) < total_elements) {
            shared_data[local_idx] = input[base_offset + local_idx];
        } else {
            shared_data[local_idx] = __float2half(0.0f);
        }

        __syncthreads();

        // Perform inclusive prefix sum using parallel algorithm
        for (int offset = 1; offset < dim_size; offset *= 2) {
            half temp = (tid >= offset) ? shared_data[tid - offset] : __float2half(0.0f);
            __syncthreads();
            if (tid < dim_size) {
                shared_data[tid] += temp;
            }
            __syncthreads();
